messages.content:
You extract entities from conversations.

Any extracted information should be returned in the same language as it was written in. Only output non-English text when the user has written full sentences or phrases in that non-English language. Otherwise, output English.

Answer with one JSON object that matches this JSON schema, and nothing else: no code fence, no text around it.
<json_schema>
{
  "$defs": {
    "ExtractedEntity": {
      "properties": {
        "name": {
          "description": "Name of the extracted entity",
          "title": "Name",
          "type": "string"
        },
        "entity_type_id": {
          "description": "ID of the classified entity type. Must be one of the provided entity_type_id integers.",
          "title": "Entity Type Id",
          "type": "integer"
        },
        "episode_indices": {
          "description": "List of episode numbers (0-indexed) this entity was extracted from. When processing a single episode, this should be [0].",
          "items": {
            "type": "integer"
          },
          "title": "Episode Indices",
          "type": "array"
        }
      },
      "required": [
        "name",
        "entity_type_id"
      ],
      "title": "ExtractedEntity",
      "type": "object"
    }
  },
  "properties": {
    "extracted_entities": {
      "description": "List of extracted entities",
      "items": {
        "$ref": "#/$defs/ExtractedEntity"
      },
      "title": "Extracted Entities",
      "type": "array"
    }
  },
  "required": [
    "extracted_entities"
  ],
  "title": "ExtractedEntities",
  "type": "object"
}
</json_schema>
